(() => {
  const products = [
    {id:'ring-a',name:'Nhẫn Aurora',variant:'Vàng 14K · Size 12',price:3290000,branch:'hcm',branchName:'Mland Quận 1',metal:'#c5a05d',stone:'#fff'},
    {id:'ring-b',name:'Nhẫn Lune',variant:'Bạc 925 · Size 11',price:1490000,branch:'hcm',branchName:'Mland Quận 1',metal:'#b6b9b7',stone:'#eaf2f5'},
    {id:'ring-c',name:'Nhẫn Solis',variant:'Vàng 18K · Size 13',price:4190000,branch:'td',branchName:'Mland Thủ Đức',metal:'#d1ad62',stone:'#fff4dc'}
  ];
  const sceneNames={catalogue:'Sản phẩm',cart:'Giỏ hàng',checkout:'Thanh toán',success:'Kết quả thanh toán',orders:'Đơn của tôi',tracking:'Theo dõi giao hàng',staff:'Staff xử lý đơn'};
  const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(n);
  const state={scene:new URLSearchParams(location.search).get('scene')||'catalogue',branch:'hcm',cart:{'ring-a':1,'ring-c':1},fulfilment:{hcm:'ship',td:'ship'},notice:''};
  const root=document.querySelector('#app');
  const icon=path=>`<svg aria-hidden="true" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${path}</svg>`;
  const cartIcon=icon('<circle cx="9" cy="20" r="1"/><circle cx="19" cy="20" r="1"/><path d="M3 4h2l2.5 11h11l2-7H7"/>');
  const pinIcon=icon('<path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>');
  const grouped=()=>Object.entries(state.cart).reduce((out,[id,qty])=>{const p=products.find(x=>x.id===id);if(p)(out[p.branch]??=[]).push({...p,qty});return out},{});
  const count=()=>Object.values(state.cart).reduce((a,b)=>a+b,0);
  const subtotal=items=>items.reduce((a,p)=>a+p.price*p.qty,0);
  const fee=branch=>state.fulfilment[branch]==='ship'?(branch==='hcm'?32000:47000):0;
  const total=()=>Object.entries(grouped()).reduce((sum,[branch,items])=>sum+subtotal(items)+fee(branch),0);
  const header=()=>`<div class="prototype-note"><strong>PROTOTYPE FE-008</strong> · Dữ liệu mô phỏng, không gọi VNPay/GHTK thật. Luồng GHTK tự động đang chờ đồng bộ tài liệu nền.</div><header class="site-header"><button class="brand" data-go="catalogue" aria-label="Mland - về sản phẩm">mland<span>.</span></button><nav class="main-nav" aria-label="Điều hướng chính"><button class="nav-btn ${state.scene==='catalogue'?'active':''}" data-go="catalogue">Sản phẩm</button><button class="nav-btn ${['orders','tracking'].includes(state.scene)?'active':''}" data-go="orders">Đơn hàng</button><button class="nav-btn ${state.scene==='staff'?'active':''}" data-go="staff">Vận hành</button></nav><div class="header-tools"><button class="branch-chip" data-go="catalogue">${pinIcon}<span>${state.branch==='hcm'?'Mland Quận 1':'Mland Thủ Đức'}</span></button><button class="icon-btn" data-go="cart">${cartIcon} Giỏ hàng <span class="cart-badge">${count()}</span></button></div></header>`;
  const reviewer=()=>`<details class="reviewer"><summary>▣ Công cụ review · ${sceneNames[state.scene]}</summary><div class="reviewer-body"><label for="scene">Màn hình / trạng thái</label><select id="scene">${Object.entries(sceneNames).map(([id,name])=>`<option value="${id}" ${id===state.scene?'selected':''}>${name}</option>`).join('')}</select><p>Chuyển nhanh giữa các màn để duyệt. Dữ liệu chỉ tồn tại trong bộ nhớ tab.</p></div></details>`;
  const footer=()=>`<footer class="footer">MLAND · FE-008 UX REVIEW · Không phải frontend production</footer>${reviewer()}`;
  const productCard=p=>`<article class="product-card"><div class="product-art" style="--metal:${p.metal};--stone:${p.stone}" role="img" aria-label="Ảnh minh họa ${p.name}"></div><div class="product-body"><p class="meta">${p.branchName}</p><h3>${p.name}</h3><p class="meta">${p.variant}</p><p class="price">${money(p.price)}</p><div class="product-actions"><button class="btn secondary" type="button">Xem chi tiết</button><button class="btn" data-add="${p.id}" type="button">Thêm vào giỏ</button></div></div></article>`;
  const catalogue=()=>`<main id="main" class="shell"><section class="hero"><div><p class="eyebrow">Ready-to-sell collection</p><h1>Chọn chi nhánh, rồi chọn món dành cho bạn.</h1><p class="lead">Mỗi sản phẩm được ghi nhớ theo chi nhánh tại thời điểm thêm vào giỏ. Bạn vẫn có thể đổi chi nhánh để mua thêm như các shop khác nhau.</p><div class="toolbar"><label class="sr-only" for="branch">Chi nhánh mua hàng</label><select class="field" id="branch"><option value="hcm" ${state.branch==='hcm'?'selected':''}>Mland Quận 1</option><option value="td" ${state.branch==='td'?'selected':''}>Mland Thủ Đức</option></select><input class="field search" aria-label="Tìm sản phẩm" placeholder="Tìm nhẫn, chất liệu, bộ sưu tập..."></div></div><div class="hero-art" aria-hidden="true"><strong>m.</strong></div></section>${state.notice?`<div class="notice success">${state.notice}</div>`:''}<div class="section-head"><div><p class="eyebrow">Catalogue</p><h2>Sản phẩm tại ${state.branch==='hcm'?'Quận 1':'Thủ Đức'}</h2></div><p>Giá hiển thị là giá tham khảo trước checkout.</p></div><section class="product-grid">${products.filter(p=>p.branch===state.branch).map(productCard).join('')}</section></main>`;
  const line=p=>`<div class="cart-line"><div class="thumb" aria-hidden="true"></div><div><div class="line-name">${p.name}</div><div class="line-options">${p.variant}</div><div class="qty" aria-label="Số lượng ${p.name}"><button data-qty="${p.id}" data-delta="-1" aria-label="Giảm số lượng">−</button><span>${p.qty}</span><button data-qty="${p.id}" data-delta="1" aria-label="Tăng số lượng">+</button></div></div><div class="line-price">${money(p.price*p.qty)}<br><button class="btn ghost danger" data-remove="${p.id}">Xóa</button></div></div>`;
  const cart=()=>{const groups=grouped(),items=Object.values(groups).flat(),sum=subtotal(items);return `<main id="main" class="shell"><p class="eyebrow">FE-008 / Cart</p><h1>Giỏ hàng của bạn</h1><p class="lead">Sản phẩm được nhóm theo đúng chi nhánh đã chọn khi thêm vào giỏ.</p>${items.length?`<div class="layout"><div class="stack">${Object.entries(groups).map(([branch,branchItems])=>`<section class="card"><div class="branch-card-head"><div class="branch-title"><span class="branch-mark">${branch==='hcm'?'Q1':'TĐ'}</span><div><h3>${branchItems[0].branchName}</h3><p class="meta">${branchItems.length} sản phẩm · xử lý riêng tại chi nhánh</p></div></div><strong>${money(subtotal(branchItems))}</strong></div>${branchItems.map(line).join('')}</section>`).join('')}</div><aside class="card summary"><h3>Tóm tắt giỏ hàng</h3><div class="summary-line"><span>${count()} sản phẩm</span><strong>${money(sum)}</strong></div><p class="meta">Phí giao hàng được tính riêng cho từng chi nhánh ở bước tiếp theo.</p><div class="summary-total"><span>Tạm tính</span><strong>${money(sum)}</strong></div><button class="btn full" data-go="checkout">Tiếp tục thanh toán →</button></aside></div>`:`<section class="success-panel"><h2>Giỏ hàng đang trống</h2><p class="lead">Chọn sản phẩm từ một hoặc nhiều chi nhánh để bắt đầu.</p><button class="btn" data-go="catalogue">Xem sản phẩm</button></section>`}</main>`};
  const fulfilmentChoice=(branch,method,title,desc)=>`<label class="choice ${state.fulfilment[branch]===method?'selected':''}"><input type="radio" name="fulfil-${branch}" value="${method}" data-fulfil="${branch}" ${state.fulfilment[branch]===method?'checked':''}><span><strong>${title}</strong><span>${desc}</span></span></label>`;
  const checkout=()=>{const groups=grouped();return `<main id="main" class="shell"><div class="steps"><div class="step active"><span>1</span>Giỏ hàng</div><i class="step-line"></i><div class="step active"><span>2</span>Giao nhận</div><i class="step-line"></i><div class="step"><span>3</span>VNPay</div></div><p class="eyebrow">Grouped checkout</p><h1>Kiểm tra trước khi thanh toán</h1><p class="lead">Mỗi chi nhánh là một đơn riêng, nhưng bạn thanh toán tổng cộng đúng một lần.</p><div class="notice">Phí GHTK dưới đây là dữ liệu mô phỏng. Production phải lấy báo giá server-to-server và không để trình duyệt gọi GHTK trực tiếp.</div><div class="layout"><div class="stack">${Object.entries(groups).map(([branch,items])=>`<section class="card"><div class="branch-card-head"><div class="branch-title"><span class="branch-mark">${branch==='hcm'?'Q1':'TĐ'}</span><div><h3>${items[0].branchName}</h3><p class="meta">Đơn chi nhánh · ${items.reduce((a,p)=>a+p.qty,0)} sản phẩm</p></div></div><strong>${money(subtotal(items))}</strong></div>${items.map(p=>`<div class="summary-line"><span>${p.name} × ${p.qty}</span><strong>${money(p.price*p.qty)}</strong></div>`).join('')}<div class="fulfilment">${fulfilmentChoice(branch,'ship','Giao qua GHTK','Theo dõi trạng thái trong Mland')}${fulfilmentChoice(branch,'pickup','Nhận tại cửa hàng','Không tính phí vận chuyển')}</div>${state.fulfilment[branch]==='ship'?`<div class="address"><strong>Nguyễn An Linh · 0912 345 678</strong><br>18 Nguyễn Gia Trí, Bình Thạnh, TP.HCM <button class="btn ghost">Thay đổi</button></div><div class="fee-box"><span>Phí GHTK từ ${items[0].branchName}</span><strong>${money(fee(branch))}</strong></div>`:`<div class="address">Nhận tại ${items[0].branchName}. Thành viên phải xác minh danh tính khi nhận.</div>`}</section>`).join('')}</div><aside class="card summary"><h3>Một lần thanh toán</h3>${Object.entries(groups).map(([branch,items])=>`<div class="summary-line"><span>${items[0].branchName}</span><strong>${money(subtotal(items)+fee(branch))}</strong></div><div class="summary-line"><span>└ Sản phẩm</span><span>${money(subtotal(items))}</span></div><div class="summary-line"><span>└ Phí giao</span><span>${money(fee(branch))}</span></div>`).join('')}<div class="summary-total"><span>Tổng thanh toán</span><strong>${money(total())}</strong></div><p class="meta">Bạn sẽ được chuyển sang VNPay. Đơn chỉ được xác nhận sau khi server kiểm chứng thanh toán.</p><button class="btn full" data-go="success">Thanh toán qua VNPay →</button></aside></div></main>`};
  const success=()=>`<main id="main" class="shell"><section class="success-panel"><div class="success-icon">✓</div><p class="eyebrow">Verified payment · Mock</p><h2>Thanh toán đã được xác nhận</h2><p class="lead">Một giao dịch ${money(total())} đã áp dụng cho 2 đơn chi nhánh. Hệ thống đang tạo vận đơn GHTK cho từng đơn giao tận nơi.</p><div class="notice">Nếu tạo vận đơn thất bại, đơn đã trả tiền vẫn được giữ ở trạng thái “Chờ tạo vận đơn” để Staff theo dõi và retry an toàn.</div><div class="product-actions"><button class="btn secondary" data-go="orders">Xem đơn hàng</button><button class="btn" data-go="tracking">Theo dõi giao hàng →</button></div></section></main>`;
  const orders=()=>`<main id="main" class="shell"><p class="eyebrow">Member / Orders</p><h1>Đơn hàng của tôi</h1><p class="lead">Mỗi chi nhánh có mã đơn và tiến trình giao nhận riêng.</p><div class="toolbar"><button class="btn secondary">Tất cả</button><button class="btn secondary">Đang xử lý</button><button class="btn secondary">Đang giao</button><button class="btn secondary">Hoàn thành</button></div><section class="order-list"><article class="order-row"><div><p class="meta">ML-Q1-261024-0142 · Mland Quận 1</p><h3>Nhẫn Aurora</h3><span class="status green">GHTK đang giao</span></div><div class="order-total"><p class="meta">Tổng đơn</p><strong>${money(3322000)}</strong></div><button class="btn secondary" data-go="tracking">Xem chi tiết</button></article><article class="order-row"><div><p class="meta">ML-TD-261024-0143 · Mland Thủ Đức</p><h3>Nhẫn Solis</h3><span class="status">Đang chuẩn bị</span></div><div class="order-total"><p class="meta">Tổng đơn</p><strong>${money(4237000)}</strong></div><button class="btn secondary" data-go="tracking">Xem chi tiết</button></article></section></main>`;
  const tracking=()=>`<main id="main" class="shell"><button class="btn ghost" data-go="orders">← Quay lại danh sách</button><p class="eyebrow">ML-Q1-261024-0142</p><h1>Đơn hàng đang trên đường giao</h1><div class="layout"><section class="card"><div class="branch-card-head"><div><p class="meta">Trạng thái GHTK gần nhất</p><h2>Đang giao hàng</h2></div><span class="status green">Cập nhật 14:32 · 24/10/2026</span></div><div class="notice success">Dự kiến giao: 25/10/2026. Đây là ước tính do đơn vị vận chuyển cung cấp, không phải cam kết thời gian.</div><div class="tracking"><div class="track-event current"><h3>Đang giao hàng</h3><p>Trạng thái mới nhất đã được đồng bộ từ GHTK.</p></div><div class="track-event"><h3>Đã bàn giao cho GHTK</h3><p>09:10 · 24/10/2026</p></div><div class="track-event"><h3>Đơn hàng đã được chuẩn bị</h3><p>17:45 · 23/10/2026</p></div></div><p class="meta">Member chỉ thấy trạng thái chuẩn hóa mới nhất, thời gian cập nhật và ngày dự kiến; không hiển thị raw webhook.</p></section><aside class="card"><h3>Thông tin đơn</h3><div class="summary-line"><span>Chi nhánh</span><strong>Mland Quận 1</strong></div><div class="summary-line"><span>Mã vận đơn</span><strong>GHTK-MOCK-88421</strong></div><div class="summary-line"><span>Sản phẩm</span><strong>Nhẫn Aurora × 1</strong></div><div class="summary-line"><span>Phí giao</span><strong>${money(32000)}</strong></div><div class="summary-total"><span>Tổng đơn</span><strong>${money(3322000)}</strong></div></aside></div></main>`;
  const staff=()=>`<main id="main" class="shell"><p class="eyebrow">Staff workspace / Quận 1</p><h1>Xử lý đơn bán lẻ</h1><p class="lead">Staff chỉ nhìn thấy và thao tác các đơn thuộc chi nhánh được phân công.</p><div class="notice">Màn vận hành nháp. Backend phải kiểm tra quyền, trạng thái hiện tại và thanh toán đã xác minh.</div><section class="card"><div class="toolbar"><input class="field search" aria-label="Tìm đơn" placeholder="Tìm mã đơn hoặc thành viên"><select class="field" aria-label="Lọc trạng thái"><option>Chờ xử lý</option><option>Đang chuẩn bị</option><option>Chờ bàn giao</option></select></div><table class="staff-table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Giao nhận</th><th>Trạng thái</th><th>Hành động</th></tr></thead><tbody><tr><td><strong>ML-Q1-261024-0142</strong><br><span class="meta">Đã thanh toán</span></td><td>Nguyễn An Linh</td><td>GHTK<br><span class="meta">GHTK-MOCK-88421</span></td><td><span class="status">Đang chuẩn bị</span></td><td><button class="btn secondary">Đánh dấu đã chuẩn bị</button></td></tr><tr><td><strong>ML-Q1-261024-0138</strong><br><span class="meta">Đã thanh toán</span></td><td>Trần Minh</td><td>Nhận tại cửa hàng</td><td><span class="status green">Sẵn sàng nhận</span></td><td><button class="btn secondary">Xác minh & bàn giao</button></td></tr></tbody></table></section></main>`;
  const views={catalogue,cart,checkout,success,orders,tracking,staff};
  function render(focus=false){if(!views[state.scene])state.scene='catalogue';root.innerHTML=header()+views[state.scene]()+footer();bind();document.title=`Mland · ${sceneNames[state.scene]} · Prototype FE-008`;const heading=document.querySelector('h1');heading?.setAttribute('tabindex','-1');if(focus)requestAnimationFrame(()=>heading?.focus({preventScroll:true}))}
  function go(scene){state.scene=scene;state.notice='';history.replaceState(null,'',`?scene=${scene}`);render(true);scrollTo({top:0,behavior:'smooth'})}
  function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));document.querySelector('#scene')?.addEventListener('change',e=>go(e.target.value));document.querySelector('#branch')?.addEventListener('change',e=>{state.branch=e.target.value;render()});document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>{state.cart[b.dataset.add]=(state.cart[b.dataset.add]||0)+1;state.notice=`Đã thêm sản phẩm từ ${products.find(p=>p.id===b.dataset.add).branchName}.`;render()}));document.querySelectorAll('[data-qty]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.qty;state.cart[id]=Math.max(0,state.cart[id]+Number(b.dataset.delta));if(!state.cart[id])delete state.cart[id];render()}));document.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{delete state.cart[b.dataset.remove];render()}));document.querySelectorAll('[data-fulfil]').forEach(r=>r.addEventListener('change',()=>{state.fulfilment[r.dataset.fulfil]=r.value;render()}))}
  render();
})();
